changeSet.sql:
SET IMPLICIT_TRANSACTIONS OFF begin Declare @Existing_Comp_level tinyint, @Required_Comp_level tinyint = 140, @database_name nvarchar(128), @sqlstmt nvarchar(2000), @Error int=0;
Declare cur_dbase cursor read_only for SELECT dbase.name DBName from sys.databases dbase where name like 'd3s[_]%' and Compatibility_Level < @Required_Comp_level;
open cur_dbase fetch next from cur_dbase into @database_name;
while @@fetch_status = 0 and @Error = 0 begin BEGIN TRY set @sqlstmt = 'ALTER DATABASE ' + @database_name + ' SET COMPATIBILITY_LEVEL = ' + cast(@Required_Comp_level as varchar(10)) EXECUTE sp_executesql @sqlstmt END TRY BEGIN CATCH Set @Error = 1; END CATCH fetch next from cur_dbase into @database_name end close cur_dbase deallocate cur_dbase end SET IMPLICIT_TRANSACTIONS ON
